def solve_equation():
    solutions = []

    # Constraints: 1 <= a <= 10, 1 <= b <= 10, 1 <= c <= 5
    for c in range(1, 6):
        target = 6**c
        for a in range(1, 11):
            for b in range(1, 11):
                lhs = (2**a) + (3**b) + 1
                if lhs == target:
                    solutions.append((a, b, c))

    return solutions

solutions = solve_equation()
print("Found solutions (a, b, c):", solutions)
